-- Productgalerijen hoodie en sweater, zoals ze live staan.
--
-- Bron: het pakket 'MOSE final' uit Downloads, V3 van 17 oktober 2026. Zes
-- beelden per kleur in de voorgeschreven volgorde, geen modelgegevens (het
-- leesmij verbiedt het overnemen van namen, lengtes en maten van de eerdere
-- modellen), en per kleur een eigen hoofdfoto zodat de kleurkeuze de hele
-- galerij en de productkaart wisselt.
--
-- Deze migratie legt vast wat er al draait. De beelden zijn via de opslag-API
-- geplaatst en de rijen via de servicerol; zonder dit bestand zou de repo niet
-- laten zien welke galerij er live staat.
--
-- Gecontroleerd: de beelden die de browser op de productpagina werkelijk laadt
-- zijn opgehaald en gehasht, en zijn alle 30 bit voor bit gelijk aan de
-- bestanden in 'MOSE final'.

DELETE FROM product_images
WHERE product_id IN (SELECT id FROM products WHERE slug IN ('mose-essential-hoodie', 'mose-classic-sweater'));

